// Flink 1.17+ KafkaSink 写法
KafkaSink<String> sink = KafkaSink.<String>builder()
    .setBootstrapServers(brokers)
    .setRecordSerializer(KafkaRecordSerializationSchema.builder()
        .setTopic("orders-eos")
        .setValueSerializationSchema(new SimpleStringSchema())
        .build())
    // 关键 1: 选择 EXACTLY_ONCE
    .setDeliveryGuarantee(DeliveryGuarantee.EXACTLY_ONCE)
    // 关键 2: transactional.id 前缀，subtask 维度自动拼 -<subtaskId>-<checkpointId>
    .setTransactionalIdPrefix("orders-job-")
    // 关键 3: 事务超时必须 > checkpoint interval + 恢复时间
    .setProperty("transaction.timeout.ms", "900000")
    .build();

env.enableCheckpointing(60_000, CheckpointingMode.EXACTLY_ONCE);
env.getCheckpointConfig().setCheckpointTimeout(120_000);
// 防止 checkpoint 失败时 fail job，保留最后一次成功状态
env.getCheckpointConfig().setTolerableCheckpointFailureNumber(2);

// 下游消费方必须配合
